  labs: [['math-algebra', 'Balance the equation'], ['math-functions', 'Function lab'], ['math-circle', 'Circles → waves'], ['math-calculus', 'Calculus you can see'], ['math-probability', 'Probability'], ['math-risk', 'Risk & ruin']],
  use: ['Position sizing, expectancy and drawdown are algebra and probability.', 'Every model in your research pipeline is a function you can graph, differentiate and test.', 'The GED Math test is algebra, geometry and data: the foundation of everything above.'],
