  books: [['Dialogue Concerning the Two Chief World Systems', 'Galileo Galilei', '1632'], ['Relativity: The Special and General Theory', 'Albert Einstein', '1916'], ['The Feynman Lectures on Physics', 'Richard Feynman', '1964'], ['QED: The Strange Theory of Light and Matter', 'Richard Feynman', '1985']],
