  archive: [['Periodic table', 'The modern periodic table.'], ['Photo 51', 'Photo 51 (1952), the X-ray image of DNA taken in Rosalind Franklin’s lab.']],
  books: [['The Sceptical Chymist', 'Robert Boyle', '1661'], ['Elements of Chemistry', 'Antoine Lavoisier', '1789'], ['The Chemical History of a Candle', 'Michael Faraday', '1861'], ['The Disappearing Spoon', 'Sam Kean', '2010']],
  watch: [['Principles of Chemical Science', 'https://ocw.mit.edu/courses/5-111sc-principles-of-chemical-science-fall-2014/', 'MIT OpenCourseWare'], ['Freshman Organic Chemistry', 'https://oyc.yale.edu/chemistry/chem-125a', 'Open Yale Courses'], ['Chemistry, with practice', 'https://www.khanacademy.org/science/chemistry', 'Khan Academy']],
