  watch: [['Introductory Biology', 'https://ocw.mit.edu/courses/7-016-introductory-biology-fall-2018/', 'MIT OpenCourseWare'], ['Principles of Evolution, Ecology and Behavior', 'https://oyc.yale.edu/ecology-and-evolutionary-biology/eeb-122', 'Open Yale Courses'], ['Biology, with practice', 'https://www.khanacademy.org/science/biology', 'Khan Academy']],
