  books: [['History of the Peloponnesian War', 'Thucydides', 'c. 400 BCE'], ['The Art of War', 'Sun Tzu', 'c. 5th century BCE'], ['On War', 'Carl von Clausewitz', '1832'], ['The Influence of Sea Power upon History', 'Alfred Thayer Mahan', '1890'], ['The Tragedy of Great Power Politics', 'John Mearsheimer', '2001'], ['Prisoners of Geography', 'Tim Marshall', '2015']],
