  books: [['The Republic', 'Plato', 'c. 375 BCE'], ['Meditations', 'Marcus Aurelius', 'c. 170'], ['Meditations on First Philosophy', 'René Descartes', '1641'], ['An Enquiry Concerning Human Understanding', 'David Hume', '1748'], ['Critique of Pure Reason', 'Immanuel Kant', '1781'], ['Thus Spake Zarathustra', 'Friedrich Nietzsche', '1883'], ['The Problems of Philosophy', 'Bertrand Russell', '1912'], ['Tao Te Ching', 'Laozi', 'c. 400 BCE']],
