  archive: [['Oracle bone script', 'Chinese oracle bones, about 3,000 years old.'], ['Rosetta Stone', 'The Rosetta Stone: one decree in three scripts.'], ['Cuneiform', 'Cuneiform tablet.'], ['Indo-European languages', 'Where the Indo-European languages are spoken, from Ireland to India.']],
  books: [['Course in General Linguistics', 'Ferdinand de Saussure', '1916'], ['Language', 'Edward Sapir', '1921'], ['The Language Instinct', 'Steven Pinker', '1994']],
  watch: [['Linguistics', 'https://thecrashcourse.com/', 'Crash Course']],
  labs: [['mandarin-tones', 'The four tones'], ['mandarin-cards', 'Flashcards'], ['mandarin-chars', 'Character building blocks']],
