  watch: [['Justice with Michael Sandel (free course)', 'https://www.edx.org/bio/michael-j-sandel', 'Harvard on edX'], ['Ethics entries', 'https://plato.stanford.edu/', 'Stanford Encyclopedia of Philosophy']],
  labs: [['evidence-questions', 'Question a claim']],
